//! Managed shell environment: `env.sh`, `init.zsh`, `init.bash` rendered from the `shell` fields
//! of present tools, plus one marked block in `~/.zshrc` / `~/.bashrc` that sources them.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

use anyhow::Result;

use crate::catalog::Catalog;
use crate::facts::Facts;
use crate::fs::{Backups, block};
use crate::state::{self, Paths};

const HEADER: &str =
    "# Generated by envira from the catalog; regenerate with `envira env`. Do not edit.\n";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rendered {
    pub env_sh: String,
    pub init_zsh: String,
    pub init_bash: String,
}

/// `~/x` -> `"$HOME/x"`; anything else double-quoted.
fn sh_path(p: &str) -> String {
    let esc = |s: &str| {
        s.replace('\\', "\\\\")
            .replace('"', "\\\"")
            .replace('`', "\\`")
    };
    if p == "~" {
        "\"$HOME\"".into()
    } else if let Some(rest) = p.strip_prefix("~/") {
        format!("\"$HOME/{}\"", esc(rest))
    } else {
        format!("\"{}\"", esc(p))
    }
}

fn sq(s: &str) -> String {
    format!("'{}'", s.replace('\'', r"'\''"))
}

/// A path under the target home written with `$HOME`.
fn home_rel(p: &Path, home: &Path) -> String {
    match p.strip_prefix(home) {
        Ok(rest) => format!("\"$HOME/{}\"", rest.display()),
        Err(_) => format!("\"{}\"", p.display()),
    }
}

pub fn render(cat: &Catalog, facts: &Facts, paths: &Paths, present: &BTreeSet<String>) -> Rendered {
    let mut env = String::from(HEADER);
    env.push_str(
        "envira_path_prepend() {\n  [ -d \"$1\" ] || return 0\n  case \":$PATH:\" in *\":$1:\"*) ;; *) PATH=\"$1:$PATH\" ;; esac\n}\n",
    );
    let mut zsh = String::from(HEADER);
    let mut bash = String::from(HEADER);
    let env_file = home_rel(&paths.config_dir.join("env.sh"), &facts.home);
    for s in [&mut zsh, &mut bash] {
        s.push_str(&format!("[ -f {env_file} ] && . {env_file}\n"));
    }

    let mut ids: Vec<&String> = cat
        .tools
        .keys()
        .filter(|id| present.contains(*id))
        .collect();
    ids.sort_by_key(|id| (cat.category(id), *id));
    for id in ids {
        let tool = &cat.tools[id];
        let Some(sh) = &tool.shell else { continue };
        let guard = format!("command -v {} >/dev/null 2>&1", tool.bin(id));
        if !sh.path.is_empty() || !sh.env.is_empty() {
            env.push_str(&format!("# {id}\n"));
            for p in &sh.path {
                env.push_str(&format!("envira_path_prepend {}\n", sh_path(p)));
            }
            for (k, v) in &sh.env {
                env.push_str(&format!("export {k}={}\n", sh_path(v)));
            }
        }
        let aliases: Vec<String> = sh
            .alias
            .iter()
            .map(|(name, target)| {
                let first = target.split_whitespace().next().unwrap_or(target);
                format!(
                    "command -v {first} >/dev/null 2>&1 && alias {name}={}\n",
                    sq(target)
                )
            })
            .collect();
        for (shell, out) in [("zsh", &mut zsh), ("bash", &mut bash)] {
            let init = sh.init.get(shell);
            if aliases.is_empty() && init.is_none() {
                continue;
            }
            out.push_str(&format!("# {id}\n"));
            for a in &aliases {
                out.push_str(a);
            }
            if let Some(init) = init {
                out.push_str(&format!("if {guard}; then\n"));
                for l in init.lines() {
                    out.push_str(&format!("  {l}\n"));
                }
                out.push_str("fi\n");
            }
        }
    }
    let shell_path: Vec<&String> = cat.env.shell_path.iter().collect();
    if !shell_path.is_empty() {
        env.push_str("# envira\n");
        for p in shell_path {
            env.push_str(&format!("envira_path_prepend {}\n", sh_path(p)));
        }
    }
    env.push_str("export PATH\nunset -f envira_path_prepend\n");
    Rendered {
        env_sh: env,
        init_zsh: zsh,
        init_bash: bash,
    }
}

/// Lines for the rc file block of a shell.
pub fn rc_block(shell: &str, paths: &Paths, facts: &Facts) -> String {
    let f = home_rel(&paths.config_dir.join(format!("init.{shell}")), &facts.home);
    format!("[ -f {f} ] && . {f}")
}

pub fn rc_files(facts: &Facts) -> Vec<(&'static str, PathBuf)> {
    // macOS terminals start login shells, and a login bash reads ~/.bash_profile, not ~/.bashrc.
    let bash = if facts.os == "macos" {
        ".bash_profile"
    } else {
        ".bashrc"
    };
    [("zsh", ".zshrc"), ("bash", bash)]
        .into_iter()
        .map(|(s, f)| (s, facts.home.join(f)))
        .filter(|(s, f)| facts.has_shell(s) || f.exists())
        .collect()
}

/// Writes the generated files and ensures the rc blocks; returns the files that changed.
pub fn install(
    cat: &Catalog,
    facts: &Facts,
    paths: &Paths,
    present: &BTreeSet<String>,
) -> Result<Vec<PathBuf>> {
    let r = render(cat, facts, paths, present);
    let mut changed = Vec::new();
    for (name, text) in [
        ("env.sh", &r.env_sh),
        ("init.zsh", &r.init_zsh),
        ("init.bash", &r.init_bash),
    ] {
        let f = paths.config_dir.join(name);
        if std::fs::read_to_string(&f).ok().as_deref() != Some(text.as_str()) {
            state::write_atomic(&f, text.as_bytes(), facts)?;
            changed.push(f);
        }
    }
    let backups = Backups::new(paths.state_dir.join("backups"));
    for (shell, rc) in rc_files(facts) {
        let content = rc_block(shell, paths, facts);
        if !block(&backups, &rc, "envira", "#", Some(&content), true)? {
            block(&backups, &rc, "envira", "#", Some(&content), false)?;
            state::chown_to_target(&rc, facts);
            changed.push(rc);
        }
    }
    Ok(changed)
}

/// Lines in rc files, outside envira's block, that duplicate what envira renders (for `doctor`).
pub fn rc_duplicates(cat: &Catalog, facts: &Facts, present: &BTreeSet<String>) -> Vec<String> {
    let mut needles: Vec<String> = Vec::new();
    for (id, t) in &cat.tools {
        if !present.contains(id) {
            continue;
        }
        let Some(sh) = &t.shell else { continue };
        needles.extend(sh.alias.keys().map(|a| format!("alias {a}=")));
        needles.extend(sh.env.keys().map(|k| format!("export {k}=")));
        needles.extend(
            sh.path
                .iter()
                .filter_map(|p| p.strip_prefix("~/"))
                .map(|p| p.to_string()),
        );
        if sh.init.values().any(|i| i.contains("fnm env")) {
            needles.push("fnm env".into());
        }
    }
    let mut out = Vec::new();
    for (_, rc) in rc_files(facts) {
        let Ok(text) = std::fs::read_to_string(&rc) else {
            continue;
        };
        let mut inside = false;
        for (n, line) in text.lines().enumerate() {
            let t = line.trim();
            if t == "# >>> envira >>>" {
                inside = true;
            } else if t == "# <<< envira <<<" {
                inside = false;
            } else if !inside
                && !t.starts_with('#')
                && needles.iter().any(|nd| t.contains(nd.as_str()))
            {
                out.push(format!(
                    "~/{}:{}: {t}",
                    rc.file_name().unwrap_or_default().to_string_lossy(),
                    n + 1
                ));
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::catalog::load::{embedded_layer, load};

    fn setup() -> (tempfile::TempDir, Catalog, Facts, Paths) {
        let d = tempfile::tempdir().unwrap();
        let facts = Facts::sample(d.path());
        let paths = Paths {
            state_dir: d.path().join(".local/state/envira"),
            config_dir: d.path().join(".config/envira"),
            cache_dir: d.path().join(".cache/envira"),
        };
        (d, load(&[embedded_layer()]).unwrap().catalog, facts, paths)
    }

    #[test]
    fn renders_only_present_tools_with_guards() {
        let (_d, cat, facts, paths) = setup();
        let present: BTreeSet<String> = ["bun", "fnm", "lsd"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let r = render(&cat, &facts, &paths, &present);
        assert!(
            r.env_sh.contains(
                "# bun\nenvira_path_prepend \"$HOME/.bun/bin\"\nexport BUN_INSTALL=\"$HOME/.bun\"\n"
            ),
            "{}",
            r.env_sh
        );
        assert!(
            !r.env_sh.contains(".cargo/bin"),
            "rust-toolchain is not present"
        );
        assert!(r.env_sh.ends_with(
            "envira_path_prepend \"$HOME/.local/bin\"\nexport PATH\nunset -f envira_path_prepend\n"
        ));
        assert!(r.init_zsh.contains(
            "[ -f \"$HOME/.config/envira/env.sh\" ] && . \"$HOME/.config/envira/env.sh\"\n"
        ));
        assert!(
            r.init_zsh
                .contains("command -v lsd >/dev/null 2>&1 && alias ls='lsd'\n")
        );
        assert!(r.init_zsh.contains("if command -v fnm >/dev/null 2>&1; then\n  eval \"$(fnm env --shell zsh)\"\n  eval \"$(fnm completions --shell zsh)\"\nfi\n"));
        assert!(r.init_bash.contains("--shell bash"));
        assert!(!r.init_bash.contains("_bun"), "bun has zsh-only init");
    }

    #[test]
    fn rendered_env_is_valid_sh_and_does_not_duplicate_path() {
        let (d, cat, facts, paths) = setup();
        std::fs::create_dir_all(d.path().join(".bun/bin")).unwrap();
        let present: BTreeSet<String> = ["bun".to_string()].into();
        install(&cat, &facts, &paths, &present).unwrap();
        let env = paths.config_dir.join("env.sh");
        let out = std::process::Command::new("sh")
            .arg("-c")
            .arg(format!(". '{0}'; . '{0}'; echo \"$PATH\"", env.display()))
            .env("HOME", d.path())
            .env("PATH", "/usr/bin:/bin")
            .output()
            .unwrap();
        let path = String::from_utf8(out.stdout).unwrap();
        assert_eq!(
            path.trim(),
            format!("{}/.bun/bin:/usr/bin:/bin", d.path().display())
        );
    }

    #[test]
    fn macos_bash_uses_the_login_profile() {
        let (d, _cat, mut facts, _paths) = setup();
        let names = |f: &Facts| {
            rc_files(f)
                .into_iter()
                .map(|(s, p)| (s, p.strip_prefix(d.path()).unwrap().display().to_string()))
                .collect::<Vec<_>>()
        };
        assert_eq!(
            names(&facts),
            [
                ("zsh", ".zshrc".to_string()),
                ("bash", ".bashrc".to_string())
            ]
        );
        facts.os = "macos".into();
        assert_eq!(
            names(&facts),
            [
                ("zsh", ".zshrc".to_string()),
                ("bash", ".bash_profile".to_string())
            ]
        );
    }

    #[test]
    fn install_is_idempotent_and_adds_one_rc_block() {
        let (d, cat, facts, paths) = setup();
        std::fs::write(d.path().join(".zshrc"), "alias ls=lsd\n").unwrap();
        let present: BTreeSet<String> = ["lsd".to_string()].into();
        let first = install(&cat, &facts, &paths, &present).unwrap();
        assert_eq!(first.len(), 5, "{first:?}");
        let second = install(&cat, &facts, &paths, &present).unwrap();
        assert!(second.is_empty(), "{second:?}");
        let zshrc = std::fs::read_to_string(d.path().join(".zshrc")).unwrap();
        assert_eq!(zshrc.matches("# >>> envira >>>").count(), 1);
        assert!(zshrc.contains(
            "[ -f \"$HOME/.config/envira/init.zsh\" ] && . \"$HOME/.config/envira/init.zsh\""
        ));
        assert_eq!(
            rc_duplicates(&cat, &facts, &present),
            vec!["~/.zshrc:1: alias ls=lsd"]
        );
    }
}
